def build_spelling_bank() -> list[GeneratedQuestion]:
    bank=[GeneratedQuestion(
        pattern_type=x["pattern_type"],subtopic=x["subtopic"],difficulty=x["difficulty"],
        expected_time_seconds=x["expected_time_seconds"],question_text=x["question_text"],
        options=tuple(x["options"]),correct_option=x["correct_option"],
        explanation=x["explanation"],fast_method=x["fast_method"]) for x in _DATA]
    if len(bank)!=100: raise AssertionError(f"Expected 100, got {len(bank)}")
    return bank
